-- CommandProject: strategic commander for the skirmish AI (generated by the launcher).
-- Appended to the game's own SkirmishAISystem.lua; SkirmishDelaySetup forks CPCommanderRun for
-- every skirmish AI brain. The game's neural attack platoons live in the engine (C++), so this
-- takes the AI's land army and fleet into its own platoons and decides where and when they fight:
--   * it measures the enemy around every possible target and only attacks with clear superiority;
--   * it gathers the army at a staging point (an ambush on the way to its base) instead of
--     sending units a few at a time;
--   * it defends its factories, extractors and expansions first;
--   * it retreats when a fight turns bad and sends badly damaged units home;
--   * fast units raid undefended mass extractors; the fleet hunts what its ships can reach.
-- Everything runs inside pcall: a problem here never stops the game or the original AI.
do
local CP_LEVEL = @LEVEL@
local CP_RAIDS = @RAIDS@
local CP_DEBUG = false

local CAT = false
local function Cat(expr)
    local ok, c = pcall(ParseEntityCategory, expr)
    if ok then return c end
    return false
end
local function Categories()
    if CAT then return CAT end
    CAT = {
        army = Cat('MOBILE LAND -ENGINEER -COMMAND -TRANSPORTATION'),
        fleet = Cat('MOBILE NAVAL -ENGINEER'),
        naval = Cat('NAVAL'),
        mobile = Cat('MOBILE -AIR'),
        structure = Cat('STRUCTURE'),
        extractor = Cat('MASSEXTRACTION'),
        factory = Cat('FACTORY'),
        experimental = Cat('EXPERIMENTAL'),
    }
    return CAT
end

local function Now()
    local t = 0
    pcall(function() t = GetGameTimeSeconds() end)
    return t
end

local function Dist(a, b)
    return VDist2(a[1], a[3], b[1], b[3])
end

local function Alive(u)
    if not u then return false end
    local ok, dead = pcall(function() return u:IsDead() end)
    return ok and not dead
end

local function Ready(u)
    if not Alive(u) then return false end
    local building = false
    pcall(function() building = u:IsBeingBuilt() end)
    if building then return false end
    local attached = false
    pcall(function() attached = u:IsUnitState('Attached') end)
    return not attached
end

local function Is(cat, u)
    if not cat then return false end
    local ok, yes = pcall(EntityCategoryContains, cat, u)
    return ok and yes
end

local function HealthFraction(u)
    local f = 1
    pcall(function() f = u:GetHealth() / math.max(1, u:GetMaxHealth()) end)
    return f
end

-- combat strength of one unit (threat from the blueprint, scaled by its health)
local function Power(u, structuresCount)
    local p = 0
    pcall(function()
        local d = u:GetBlueprint().Defense or {}
        p = (d.SurfaceThreatLevel or 0) + (d.SubThreatLevel or 0) * 0.5
    end)
    if p <= 0 and not structuresCount then
        -- units without a threat rating still count by how tough they are
        pcall(function() p = u:GetMaxHealth() / 300 end)
    end
    return p * (0.35 + 0.65 * HealthFraction(u))
end

local function Speed(u)
    local s = 0
    pcall(function() s = u:GetBlueprint().Physics.MaxSpeed or 0 end)
    return s
end

local function Centroid(units)
    local x, z, n = 0, 0, 0
    for _, u in ipairs(units) do
        local p = u:GetPosition()
        x = x + p[1]
        z = z + p[3]
        n = n + 1
    end
    if n == 0 then return false end
    local y = 0
    pcall(function() y = GetSurfaceHeight(x / n, z / n) end)
    return { x / n, y, z / n }
end

local function Spread(units, center)
    local m = 0
    for _, u in ipairs(units) do
        local d = Dist(u:GetPosition(), center)
        if d > m then m = d end
    end
    return m
end

local function EnemyPower(brain, pos, radius)
    local c = Categories()
    local total = 0
    local list = {}
    pcall(function() list = brain:GetUnitsAroundPoint(c.mobile, pos, radius, 'Enemy') or {} end)
    for _, u in ipairs(list) do
        if Ready(u) then total = total + Power(u) end
    end
    local towers = {}
    pcall(function() towers = brain:GetUnitsAroundPoint(c.structure, pos, radius, 'Enemy') or {} end)
    for _, u in ipairs(towers) do
        if Ready(u) then total = total + Power(u, true) end
    end
    return total
end

local function PowerOf(units)
    local t = 0
    for _, u in ipairs(units) do t = t + Power(u) end
    return t
end

local function CanReach(units, pos)
    local u = units[1]
    if not u then return false end
    local ok, res = pcall(function() return u:GetNavigator():CanPathToGoal(pos) end)
    if not ok then return true end
    return res and true or false
end

local function Order(units, kind, pos)
    if table.getn(units) == 0 or not pos then return end
    pcall(IssueClearCommands, units)
    if kind == 'attack' then
        pcall(IssueAggressiveMove, units, pos)
    else
        pcall(IssueMove, units, pos)
    end
end

local function Log(brain, text)
    if CP_DEBUG then LOG('*CP AI ' .. brain:GetArmyIndex() .. ': ' .. text) end
end

-- ---------------------------------------------------------------- the commander of one AI
local Commander = {}

function Commander.New(brain, home)
    local self = {
        brain = brain,
        home = home,
        squads = {
            main = { name = 'main', state = 'hold', units = {} },
            raid = { name = 'raid', state = 'hold', units = {} },
            fleet = { name = 'fleet', state = 'hold', units = {} },
        },
        platoon = false,
        difficulty = brain.DifficultyLevel or 2,
    }
    -- patience: how much stronger than the defenders the army must be before it attacks
    self.ratio = 1.35
    if self.difficulty <= 1 then self.ratio = 1.15 end
    if CP_LEVEL >= 2 then self.ratio = self.ratio + 0.15 end
    return self
end

function Commander.Enemies(self)
    local list = {}
    local mine = self.brain:GetArmyIndex()
    for _, b in ArmyBrains do
        local ok, enemy = pcall(function()
            return IsEnemy(mine, b:GetArmyIndex()) and not b:IsDefeated() and not ArmyIsCivilian(b:GetArmyIndex())
        end)
        if ok and enemy then table.insert(list, b) end
    end
    return list
end

-- the staging point: a third of the way towards the nearest enemy, at most 150 away (ambush)
function Commander.Staging(self)
    local best, bestD = false, 0
    for _, b in Commander.Enemies(self) do
        local x, z = b:GetArmyStartPos()
        local p = { x, 0, z }
        local d = Dist(self.home, p)
        if not best or d < bestD then best, bestD = p, d end
    end
    if not best or bestD <= 0 then return self.home end
    local k = math.min(150, bestD * 0.33) / bestD
    local x = self.home[1] + (best[1] - self.home[1]) * k
    local z = self.home[3] + (best[3] - self.home[3]) * k
    local y = 0
    pcall(function() y = GetSurfaceHeight(x, z) end)
    return { x, y, z }
end

function Commander.MinUnits(self)
    local t = Now()
    local n = 6 + math.floor(t / 120)
    if CP_LEVEL >= 2 then n = 8 + math.floor(t / 100) end
    return math.min(n, 30)
end

function Commander.Platoon(self)
    local ok, exists = pcall(function() return self.platoon and self.brain:PlatoonExists(self.platoon) end)
    if not (ok and exists) then
        self.platoon = false
        pcall(function() self.platoon = self.brain:MakePlatoon('', '') end)
    end
    return self.platoon
end

-- takes finished combat units into the commander's squads (out of the engine's attack platoons)
function Commander.Recruit(self)
    local c = Categories()
    local fresh = { main = {}, raid = {}, fleet = {} }
    local function take(cat, isFleet)
        if not cat then return end
        local list = {}
        pcall(function() list = self.brain:GetListOfUnits(cat, false) or {} end)
        for _, u in ipairs(list) do
            if not u.CPSquad and Ready(u) then
                local squad = 'main'
                if isFleet then
                    squad = 'fleet'
                elseif CP_RAIDS and Speed(u) >= 4 and table.getn(self.squads.raid.units) + table.getn(fresh.raid) < 5
                    and not Is(c.experimental, u) then
                    squad = 'raid'
                end
                u.CPSquad = squad
                table.insert(fresh[squad], u)
            end
        end
    end
    take(c.army, false)
    take(c.fleet, true)
    local plat = Commander.Platoon(self)
    for name, units in fresh do
        if table.getn(units) > 0 then
            if plat then
                pcall(function() self.brain:AssignUnitsToPlatoon(plat, units, 'Attack', 'None') end)
            end
            -- newcomers join whatever their squad is doing
            local sq = self.squads[name]
            if sq.state == 'attack' and sq.target then
                Order(units, 'move', sq.rally or self.home)
            else
                Order(units, 'move', sq.rally or Commander.Staging(self))
            end
        end
    end
end

-- live members; badly damaged units go home and come back when repaired
function Commander.Members(self, squad)
    local list = {}
    local hurt = {}
    for _, u in ipairs(squad.units) do
        if Alive(u) and u.CPSquad == squad.name then
            local f = HealthFraction(u)
            if u.CPWounded then
                if f > 0.8 then u.CPWounded = nil end
            elseif f < 0.3 and not Is(Categories().experimental, u) then
                u.CPWounded = true
                table.insert(hurt, u)
            end
            if not u.CPWounded then table.insert(list, u) end
        end
    end
    if table.getn(hurt) > 0 then Order(hurt, 'move', self.home) end
    return list
end

function Commander.Collect(self)
    local all = {}
    local c = Categories()
    for _, cat in { c.army, c.fleet } do
        if cat then
            local list = {}
            pcall(function() list = self.brain:GetListOfUnits(cat, false) or {} end)
            for _, u in ipairs(list) do
                if u.CPSquad and Alive(u) then table.insert(all, u) end
            end
        end
    end
    for _, sq in self.squads do sq.units = {} end
    for _, u in ipairs(all) do
        local sq = self.squads[u.CPSquad]
        if sq then table.insert(sq.units, u) end
    end
    for _, sq in self.squads do sq.members = Commander.Members(self, sq) end
end

-- places worth taking: enemy structures grouped in cells of 40, valued by what they are
function Commander.Targets(self)
    local c = Categories()
    local list = {}
    pcall(function() list = self.brain:GetUnitsAroundPoint(c.structure, self.home, 100000, 'Enemy') or {} end)
    local cells = {}
    for _, u in ipairs(list) do
        if Ready(u) then
            local p = u:GetPosition()
            local key = math.floor(p[1] / 40) .. ':' .. math.floor(p[3] / 40)
            local cell = cells[key]
            if not cell then
                cell = { pos = p, value = 0, extractors = 0 }
                cells[key] = cell
            end
            if Is(c.extractor, u) then
                cell.value = cell.value + 3
                cell.extractors = cell.extractors + 1
            elseif Is(c.factory, u) then
                cell.value = cell.value + 4
            else
                cell.value = cell.value + 1
            end
        end
    end
    local out = {}
    for _, cell in cells do table.insert(out, cell) end
    return out
end

-- threats near our own structures (factories, extractors, expansions)
function Commander.Threat(self)
    local c = Categories()
    local ours = {}
    pcall(function() ours = self.brain:GetListOfUnits(c.structure, false) or {} end)
    local centers = {}
    for _, u in ipairs(ours) do
        if Alive(u) then
            local p = u:GetPosition()
            local key = math.floor(p[1] / 60) .. ':' .. math.floor(p[3] / 60)
            if not centers[key] then centers[key] = p end
        end
    end
    local worst, worstPower = false, 0
    for _, p in centers do
        local power = EnemyPower(self.brain, p, 55)
        if power > worstPower then worst, worstPower = p, power end
    end
    return worst, worstPower
end

function Commander.PickTarget(self, squad, power, needWater)
    local best, bestScore, bestRisk = false, 0, 0
    local origin = Centroid(squad.members) or self.home
    for _, cell in Commander.Targets(self) do
        local risk = EnemyPower(self.brain, cell.pos, 45)
        if power >= risk * self.ratio and power > 0 then
            local d = Dist(origin, cell.pos)
            local score = cell.value * 10 / (1 + risk) / (1 + d / 400)
            if squad.name == 'raid' then
                -- raiders only go where nothing can shoot back
                if risk > 1 or cell.extractors == 0 then score = 0 end
            end
            if score > bestScore and CanReach(squad.members, cell.pos) then
                best, bestScore, bestRisk = cell.pos, score, risk
            end
        end
    end
    -- the fleet also hunts enemy ships it can reach
    if needWater and not best then
        local list = {}
        pcall(function() list = self.brain:GetUnitsAroundPoint(Categories().naval, origin, 100000, 'Enemy') or {} end)
        for _, u in ipairs(list) do
            if Ready(u) then
                local p = u:GetPosition()
                local risk = EnemyPower(self.brain, p, 45)
                if power >= risk * self.ratio and CanReach(squad.members, p) then
                    return p, risk
                end
            end
        end
    end
    return best, bestRisk
end

function Commander.Lead(self, squad, threatPos, threatPower)
    local members = squad.members
    local count = table.getn(members)
    if count == 0 then
        squad.state = 'hold'
        return
    end
    local power = PowerOf(members)
    local center = Centroid(members)
    local t = Now()

    -- 1. defend what is ours: intercept raiders if we can win, otherwise fall back home
    if threatPos and squad.name ~= 'raid' and (squad.name ~= 'fleet' or CanReach(members, threatPos)) then
        if power >= threatPower * 0.8 then
            if squad.state ~= 'defend' or Dist(squad.target or threatPos, threatPos) > 40 then
                squad.state = 'defend'
                squad.target = threatPos
                Order(members, 'attack', threatPos)
                Log(self.brain, squad.name .. ' defends')
            end
            return
        elseif squad.state ~= 'home' then
            squad.state = 'home'
            squad.target = false
            Order(members, 'move', self.home)
            return
        end
    elseif squad.state == 'defend' or squad.state == 'home' then
        squad.state = 'hold'
        squad.ordered = false
    end

    -- 2. in a fight: retreat if it turned bad, look for the next target when it is won
    if squad.state == 'attack' and center then
        local enemyHere = EnemyPower(self.brain, center, 50)
        local oursHere = 0
        for _, u in ipairs(members) do
            if Dist(u:GetPosition(), center) < 50 then oursHere = oursHere + Power(u) end
        end
        if enemyHere > oursHere * 1.2 then
            squad.state = 'retreat'
            squad.until_ = t + 25
            squad.target = false
            Order(members, 'move', squad.rally or self.home)
            Log(self.brain, squad.name .. ' retreats')
            return
        end
        if squad.target and Dist(center, squad.target) < 30 and EnemyPower(self.brain, squad.target, 45) <= 0.5 then
            squad.target = false
            squad.state = 'hold'
        else
            return
        end
    end
    if squad.state == 'retreat' and t < (squad.until_ or 0) then return end

    -- 3. choose a target the army can actually beat; gather first, then strike together
    local minUnits = Commander.MinUnits(self)
    if squad.name == 'raid' then minUnits = 2 end
    if squad.name == 'fleet' then minUnits = math.max(3, math.floor(minUnits / 2)) end
    if count >= minUnits then
        local target, risk = Commander.PickTarget(self, squad, power, squad.name == 'fleet')
        if not target and count >= minUnits * 3 then
            -- a very large army accepts an even fight
            local saved = self.ratio
            self.ratio = 1.0
            target, risk = Commander.PickTarget(self, squad, power, squad.name == 'fleet')
            self.ratio = saved
        end
        if target then
            if squad.name ~= 'raid' and center and Spread(members, center) > 35 and squad.state ~= 'gather' then
                squad.state = 'gather'
                squad.gatherUntil = t + 40
                squad.rally = center
                Order(members, 'move', center)
                return
            end
            if squad.state == 'gather' and center and Spread(members, center) > 35 and t < (squad.gatherUntil or 0) then
                return
            end
            squad.state = 'attack'
            squad.target = target
            Order(members, 'attack', target)
            Log(self.brain, squad.name .. ' attacks with ' .. count .. ' units')
            return
        end
    end

    -- 4. nothing worth it yet: wait at the ambush point on the way to our base
    if squad.state ~= 'hold' or not squad.ordered then
        squad.state = 'hold'
        squad.rally = Commander.Staging(self)
        if squad.name == 'fleet' and not CanReach(members, squad.rally) then squad.rally = center end
        squad.ordered = true
        Order(members, 'attack', squad.rally)
    end
end

function Commander.Run(self)
    local period = 4
    if CP_LEVEL >= 2 then period = 3 end
    WaitSeconds(10)
    while not self.brain:IsDefeated() do
        local ok, err = pcall(function()
            Commander.Recruit(self)
            Commander.Collect(self)
            local threatPos, threatPower = Commander.Threat(self)
            for _, sq in self.squads do
                Commander.Lead(self, sq, threatPos, threatPower)
            end
        end)
        if not ok then
            WARN('*CommandProject AI commander: ' .. tostring(err))
            WaitSeconds(10)
        end
        WaitSeconds(period)
    end
end

function CPCommanderRun(brain, home)
    if not brain or brain.BrainType == 'Human' then return end
    local self = Commander.New(brain, home or { 0, 0, 0 })
    Commander.Run(self)
end
end
